def compute(vars):
    values = {
        2019: vars["v1"],
        2018: vars["v2"],
        2017: vars["v3"],
    }
    year = min(values, key=values.get)
    return {
        "value": year,
        "trace": {
            "interest_income_by_year": values,
            "output_meta": {"currency": None, "scale": None, "unit": "fiscal_year"},
        },
    }
